 check('stride follows distance, stops at rest, freezes on pause and excludes dashing',()=>{const r=reset();r.enemies=[];r.spawn=999;r.attack=999;t.keys.clear();t.keys.add('d');const start=r.x;for(let i=0;i<8;i++)t.update(.025);assert(r.anim.moving);assert(Math.abs(r.anim.strideDistance-(r.x-start))<.01);t.keys.clear();const stride=r.anim.strideDistance;t.update(.025);assert(!r.anim.moving);assert.equal(r.anim.strideDistance,stride);r.paused=true;t.keys.add('d');t.update(.05);assert.equal(r.anim.strideDistance,stride);r.paused=false;t.dash();t.update(.025);assert.equal(r.anim.strideDistance,stride);assert(!r.anim.moving);t.keys.clear();t.endRun(false,true);t.closeModal()});
 check('moving attacks preserve the complete original pose without grafted legs in both facings',()=>{for(const w of t.weapons){const h=t.heroes.find(h=>h.classId===w.classId),id=t.actionBindings[w.id]?.attack,d=id&&t.providedActions[id];for(const heading of [-1,1]){const hashes=[];for(const moving of [false,true]){t.ctx.clearRect(0,0,800,500);t.run={hero:h,weapon:w,x:300,y:250,time:0,heading,aim:0,dashTime:0,anim:{moving,strideDistance:16,walkClock:0,attackLeft:.2,skillLeft:0,hurtLeft:0},action:d?{id,kind:'attack',elapsed:d.attackDuration*.5,duration:d.attackDuration}:null};t.drawClassHero(t.ctx,300,250,h,0,1);hashes.push(crypto.createHash('sha256').update(t.ctx.getImageData(180,100,260,200).data).digest('hex'))}assert.equal(hashes[0],hashes[1],w.id+' full attack silhouette')}}t.run=null});
 check('all walking variants retain complete-body metadata and loaded external atlases',()=>{const manifest=JSON.parse(fs.readFileSync(path.join(root,'tests/walking-manifest.json')));assert.equal(Object.keys(manifest).length,31);for(const [id,d]of Object.entries(manifest)){assert.equal(d.completeBody,true,id);assert(t.spriteImages[id]?.loaded);assert(d.source.includes(id));assert.equal(d.frames,8)}});

 check('nine new weapon action bindings include eight registered attack and skill poses each',()=>{const ids=['thorn','eclipselantern','moonlit','void','cannon','harbinger','repeater','bow','phoenix'];for(const id of ids){const b=t.actionBindings[id];assert.equal(b.attack,'weaponv2_'+id);assert.equal(b.skill,b.attack);const d=t.providedActions[b.attack];assert.equal(d.frames,8);assert.equal(d.release,4);assert(d.points.every(p=>p.cropRight>0&&p.cropRight<256));const w=t.weapons.find(w=>w.id===id);if(!['keeper','brawler'].includes(w.classId))assert(d.points.every(p=>Array.isArray(p.muzzle)))}assert.equal(Object.keys(t.providedActions).length,32)});
 check('all nine weapons render their new animation and release the skill after frame four',()=>{for(const id of ['thorn','eclipselantern','moonlit','void','cannon','harbinger','repeater','bow','phoenix']){reset();t.endRun(false,true);t.closeModal();t.save=t.fresh();const w=t.weapons.find(w=>w.id===id),h=t.heroes.find(h=>h.classId===w.classId);t.save.hero=h.id;t.save.unlocked.push(h.id);t.save.unlockedWeapons.push(w.id);t.save.weapon=w.id;t.save.classLoadouts={[h.classId]:w.id};t.startRun();const r=t.run;r.enemies=[];t.spawnEnemy(false,0);const enemy=r.enemies[0];enemy.x=r.x+50;enemy.y=r.y;enemy.hp=enemy.maxHp=1e8;r.skillCd=0;t.skill();assert.equal(t.currentAction(r).id,'weaponv2_'+id);assert(r.skillPending);const before=enemy.hp;t.tickSpriteAnimation(r,.4);assert.equal(enemy.hp,before);assert.equal(r.shots.length,0);assert.equal(t.currentAction(r).frame,3);t.tickSpriteAnimation(r,.11);assert.equal(r.skillPending,null);assert.equal(t.currentAction(r).frame,4);assert(enemy.hp<before||r.shots.length>0);for(const heading of [-1,1]){r.heading=heading;t.ctx.clearRect(0,0,800,500);t.drawClassHero(t.ctx,200,180,r.hero,.5);const point=t.firingPoint(r);assert(Number.isFinite(point.x)&&Number.isFinite(point.y));if(r.shots.length)assert(Math.abs(Math.abs(point.x-r.x)-Math.abs(t.providedActions['weaponv2_'+id].points[4].muzzle[0]))<.001)}t.endRun(false,true);t.closeModal()}});
 check('high attack speed accelerates the clip and still completes recovery before restarting',()=>{const r=reset();r.weapon=t.weapons.find(w=>w.id==='moonlit');r.rate=.08;r.invuln=1e6;r.enemies=[];t.spawnEnemy(false,0);r.enemies[0].x=r.x+50;r.enemies[0].y=r.y;r.enemies[0].hp=r.enemies[0].maxHp=1e8;r.attack=0;let prior=null,restarts=0,recovery=false;for(let i=0;i<40;i++){t.update(.025);const a=t.currentAction(r);if(a){if(a.frame>=6)recovery=true;if(prior&&a.elapsed<prior.elapsed){assert(prior.elapsed+.025>=prior.duration-.001);restarts++}assert(a.duration<=.16);prior={elapsed:a.elapsed,duration:a.duration}}}assert(restarts>=2);assert(recovery);t.endRun(false,true);t.closeModal()});

 const finishConversation=(choice='care')=>{let n=0;while(t.run?.story?.dialog){assert(++n<12,'dialogue terminates');const d=t.run.story.dialog,buttons=els['#modalActions'].children;buttons[d.kind==='report'&&d.stage===4&&d.page===2&&choice==='proof'?1:0].click()}};
 const storyReset=()=>{const r=reset('story');finishConversation();return r};
 const talk=(r,stage)=>{const n=t.adventureNpc(r,stage);r.x=n.x;r.y=n.y;t.tickAdventure(r);t.storyInteract();finishConversation()};
 const collectStage=(r,stage)=>{for(const p of t.storyQuestPoints(r,stage)){r.x=p.x;r.y=p.y;t.storyInteract()}};
 function completeDistrict(r,stage,choice='care'){
  const b=t.storyRoomBoxes[stage];r.x=b.cx;r.y=b.cy;t.tickAdventure(r);talk(r,stage);if(stage===2)collectStage(r,2);if(stage===3)collectStage(r,3);
  assert(r.story.rooms[stage].fighting,'objective starts district '+stage);
  for(let wave=(stage-1)*20+1;wave<=stage*20;wave++){
   assert.equal(r.wave,wave);t.advanceWaves(r,.01);assert(r.enemies.length>0,'authored encounter '+wave);assert(r.enemies.every(e=>!t.storySolid(r,e.x,e.y,7)),'spawn inside floor');
   if(wave%20===0){const e=r.enemies.find(e=>e.boss);assert(e);r.x=e.x;r.y=e.y;t.hit(e,1e12,true);t.resolveBoss(r)}else{r.enemies=[];r.drops=[];t.advanceWaves(r,1)}
  }
  assert(r.story.rooms[stage].cleared);assert(!r.story.rooms[stage].fighting);assert(!r.story.rooms[stage].reported);const n=t.adventureNpc(r,stage);r.x=n.x;r.y=n.y;t.storyInteract();finishConversation(choice);assert(r.story.rooms[stage].reported);
 }
 check('story starts in a safe physical outpost and waits for an NPC conversation',()=>{const r=storyReset();assert.equal(r.story.unlocked,0);assert.equal(r.enemies.length,0);t.advanceWaves(r,1000);assert.equal(r.wave,1);assert.equal(r.enemies.length,0);assert(t.storyGoal(r).includes('Mara'));talk(r,0);assert.equal(r.story.unlocked,1);assert(!r.paused);assert(t.validExpedition(t.packRun(r)));t.endRun(false,true);t.closeModal()});
 check('all six tile maps have connected playable routes and reachable witnesses and mechanisms',()=>{const r=storyReset();for(let ch=1;ch<=6;ch++){r.chapter=ch;t.setupChapter(r);r.story.unlocked=5;r.story.discovered=[0,1,2,3,4,5];r.story.destroyed=t.storyTerrain(ch).props.map(p=>p.id);const seen=new Set(),q=[6*48+8];seen.add(q[0]);for(let h=0;h<q.length;h++){const k=q[h],x=k%48,y=Math.floor(k/48);for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const xx=x+dx,yy=y+dy,j=yy*48+xx;if(xx<0||xx>=48||yy<0||yy>=30||seen.has(j)||t.storySolid(r,xx*50+25,yy*50+25,11))continue;seen.add(j);q.push(j)}}for(let stage=0;stage<6;stage++){const n=t.adventureNpc(r,stage);assert(!t.storySolid(r,n.x,n.y,11),'NPC floor '+ch+':'+stage);assert(seen.has(Math.floor(n.y/50)*48+Math.floor(n.x/50)),'NPC reachable '+ch+':'+stage)}for(const stage of[2,3])for(const p of t.storyQuestPoints(r,stage))assert(seen.has(Math.floor(p.y/50)*48+Math.floor(p.x/50)));assert(seen.size>450)}t.endRun(false,true);t.closeModal()});
 check('walking and fast dashes cannot cross locked gates or solid walls',()=>{const r=storyReset();r.x=750;r.y=375;t.keys.add('d');for(let i=0;i<10;i++)t.update(.05);t.dash();for(let i=0;i<10;i++)t.update(.025);t.keys.clear();assert(r.x<=789.01);assert(!t.storySolid(r,r.x,r.y,11));const prev=r.x;t.update(.05);assert(!r.anim.moving);assert.equal(r.x,prev);r.story.unlocked=1;t.storyConstrainMove(r,750,375,950,375,11);assert(r.x>900);r.story.rooms[1].fighting=true;r.story.combatRoom=1;t.storyConstrainMove(r,950,375,750,375,11);assert(r.x>=860.99);assert(!t.storySolid(r,r.x,r.y,11));t.endRun(false,true);t.closeModal()});
 check('projectiles stop at walls and destructible crates, with rewards only once',()=>{const r=storyReset();r.story.unlocked=1;const b=t.storyRoomBoxes[1],m=t.storyTerrain(1);let tile=null;for(let y=b.ty;y<b.ty+9;y++)for(let x=b.tx;x<b.tx+12;x++)if(m.tiles[y][x]===2)tile={x:x*50,y:y*50};assert(tile);const shot={x:tile.x+80,y:tile.y+25,vx:1000,vy:0,t:2,enemy:true,dmg:10};assert(t.storyProjectileCollision(r,shot,tile.x-40,tile.y+25));assert.equal(shot.t,0);const p=m.props[0],before=t.save.gold,s={x:p.x+55,y:p.y+20,t:2,enemy:false,dmg:1e6};assert(t.storyProjectileCollision(r,s,p.x-20,p.y+20));assert(r.story.destroyed.includes(p.id));assert.equal(t.save.gold,before+2);t.storyProjectileCollision(r,{...s,t:2},p.x-20,p.y+20);assert.equal(t.save.gold,before+2);assert(!t.storySolid(r,p.x+20,p.y+20,10));t.endRun(false,true);t.closeModal()});
 check('enemy movement stays on walkable terrain and steers around cover',()=>{const r=storyReset();talk(r,0);r.story.activeRoom=1;r.story.discovered.push(1);const b=t.storyRoomBoxes[1];r.x=b.cx-200;r.y=b.cy+80;t.startStoryEncounter(r,1);t.spawnEnemy(false,0);const e=r.enemies[0],p=t.storyFreePoint(r,1,{x:b.cx+180,y:b.cy-100});e.x=p.x;e.y=p.y;let moved=0;for(let i=0;i<160;i++){const from={x:e.x,y:e.y},a=t.storySteeringAngle(e,r,Math.atan2(r.y-e.y,r.x-e.x));e.x+=Math.cos(a)*3;e.y+=Math.sin(a)*3;t.storyMoveEnemy(r,e,from);assert(!t.storySolid(r,e.x,e.y,7));moved+=Math.hypot(e.x-from.x,e.y-from.y)}assert(moved>100);t.endRun(false,true);t.closeModal()});
 check('story waves require clearing enemies and cannot advance on a timer alone',()=>{const r=storyReset();talk(r,0);const b=t.storyRoomBoxes[1];r.x=b.cx;r.y=b.cy;t.tickAdventure(r);talk(r,1);t.advanceWaves(r,.01);const first=r.wave,count=r.enemies.length;assert(count>=3);t.advanceWaves(r,1000);assert.equal(r.wave,first);assert.equal(r.enemies.length,count);r.enemies=[];t.advanceWaves(r,1);assert.equal(r.wave,first+1);assert.equal(r.story.unlocked,1);t.endRun(false,true);t.closeModal()});
 check('mid-dialogue Continue restores the exact speaker, page and quest state',()=>{const r=storyReset();talk(r,0);const b=t.storyRoomBoxes[1];r.x=b.cx;r.y=b.cy;t.tickAdventure(r);const n=t.adventureNpc(r,1);r.x=n.x;r.y=n.y;t.storyInteract();assert.equal(r.story.dialog.kind,'brief');els['#modalActions'].children[0].click();assert.equal(r.story.dialog.page,1);const before=t.save.gold;t.leaveToHome();assert(t.resumeRun());assert(t.run.paused);assert.equal(t.run.story.dialog.page,1);finishConversation();assert(t.run.story.rooms[1].fighting);assert.equal(t.save.gold,before);assert(t.validExpedition(t.packRun(t.run)));t.endRun(false,true);t.closeModal()});
 check('completed district gates and NPC rewards survive Continue without duplicate rewards',()=>{const r=storyReset();talk(r,0);completeDistrict(r,1);const before=t.save.gold;t.leaveToHome();assert(t.resumeRun());const resumed=t.run;assert(resumed.story.rooms[1].reported);assert.equal(resumed.story.unlocked,2);talk(resumed,1);assert.equal(t.save.gold,before);assert(!resumed.story.dialog);t.storyOverlay('map');assert(resumed.paused);els['#modalActions'].children[0].click();assert(!resumed.paused);assert(t.validExpedition(t.packRun(resumed)));t.endRun(false,true);t.closeModal()});
 check('legacy Story expeditions migrate into solid maps without losing their wave or purchases',()=>{const r=reset();r.mode='story';r.chapter=2;r.wave=47;const data=t.packRun(r);data.mode='story';delete data.state.story;t.save.chapterUnlocked=2;t.leaveToHome();const gold=t.save.gold;assert(t.resumeRun(data));assert.equal(t.run.wave,47);assert.equal(t.run.story.unlocked,3);assert(t.run.story.rooms[1].reported&&t.run.story.rooms[2].reported);assert(!t.storySolid(t.run,t.run.x,t.run.y,11));assert.equal(t.save.gold,gold);assert(t.validExpedition(t.packRun(t.run)));t.endRun(false,true);t.closeModal()});
 check('invalid story room, dialogue and quest data is rejected safely',()=>{const r=storyReset(),data=t.packRun(r);for(const mutate of [x=>x.state.story.rooms=[],x=>x.state.story.unlocked=8,x=>x.state.story.dialog={kind:'unknown',stage:0,page:0},x=>x.state.story.relics=['fake'],x=>x.state.story.destroyed=['not_a_crate']]){const d=JSON.parse(JSON.stringify(data));mutate(d);assert(!t.validExpedition(d))}assert(t.validExpedition(data));t.endRun(false,true);t.closeModal()});
 check('the entire story progresses through thirty NPC objectives, 600 cleared waves and a saved ending',()=>{const r=storyReset();let districts=0;for(let ch=1;ch<=6;ch++){assert.equal(r.chapter,ch);talk(r,0);for(let stage=1;stage<=5;stage++){completeDistrict(r,stage,ch%2?'care':'proof');districts++;assert.equal(r.chapter,ch,'no automatic chapter jump');assert.equal(r.wave,stage*20);assert(t.validExpedition(t.packRun(r)))}const exit=t.storyTargets(r).find(o=>o.kind==='exit');assert(exit);r.x=exit.x;r.y=exit.y;t.storyInteract();if(ch<6){assert.equal(r.chapter,ch+1);finishConversation();assert.equal(r.wave,1)}}assert.equal(districts,30);assert(r.pendingEnding);assert.equal(t.save.journal.length,36);assert.equal(Object.keys(r.storyChoices).length,6);assert.equal(r.storyRescues,6);t.finishStory('release');assert.equal(t.run,null);assert(t.save.storyComplete);assert.equal(t.save.ending,'release');assert.equal(t.save.records.story,600);t.closeModal()});
 check('mechanisms must both be activated before the third district starts fighting',()=>{const r=storyReset();r.story.unlocked=3;r.story.discovered=[0,1,2,3];r.story.activeRoom=3;r.wave=41;talk(r,3);assert(!r.story.rooms[3].fighting);t.advanceWaves(r,999);assert.equal(r.enemies.length,0);const points=t.storyQuestPoints(r,3);r.x=points[0].x;r.y=points[0].y;t.storyInteract();assert.equal(r.story.switches.length,1);assert(!r.story.rooms[3].fighting);r.x=points[1].x;r.y=points[1].y;t.storyInteract();assert.equal(r.story.switches.length,2);assert(r.story.rooms[3].fighting);assert(t.storyGateClosed(r,t.storyTerrain(r.chapter).gates[2]));t.endRun(false,true);t.closeModal()});
 check('the second district stays locked until all three physical memory items are recovered',()=>{const r=storyReset();r.story.unlocked=2;r.story.discovered=[0,1,2];r.story.activeRoom=2;r.wave=40;const o=r.story.rooms[2];o.entered=true;o.briefed=true;o.cleared=true;o.fighting=false;talk(r,2);assert(!o.reported);assert.equal(r.story.unlocked,2);collectStage(r,2);assert.equal(r.story.relics.length,3);talk(r,2);assert(o.reported);assert.equal(r.story.unlocked,3);t.endRun(false,true);t.closeModal()});
 check('partial crate damage, recovered items, switches and choices survive an expedition save',()=>{const r=storyReset();talk(r,0);r.story.relics=['relic_2_0'];r.story.switches=['switch_3_0'];r.story.destroyed=['crate_1_0'];r.story.propDamage.crate_1_1=13;r.storyChoices[1]='proof';const packed=t.packRun(r);assert(t.validExpedition(packed));t.leaveToHome();assert(t.resumeRun());assert.deepEqual(Array.from(t.run.story.relics),['relic_2_0']);assert.deepEqual(Array.from(t.run.story.switches),['switch_3_0']);assert.deepEqual(Array.from(t.run.story.destroyed),['crate_1_0']);assert.equal(t.run.story.propDamage.crate_1_1,13);assert.equal(t.run.storyChoices[1],'proof');t.endRun(false,true);t.closeModal()});
 check('touch Interact breaks a nearby crate without walking through it',()=>{const r=storyReset();r.story.unlocked=1;r.story.discovered=[0,1];const p=t.storyTerrain(1).props[0];r.x=p.x-16;r.y=p.y+20;t.tickAdventure(r);assert.equal(t.nearestStoryTarget(r).id,p.id);assert(!els['#storyInteract'].disabled);els['#storyInteract'].click();assert(r.story.destroyed.includes(p.id));t.endRun(false,true);t.closeModal()});
