 function bossScene(ch,tier,mode='campaign'){
  const r=reset(mode);if(mode==='story')finishConversation();r.chapter=ch;t.setupChapter(r);r.wave=tier*20;r.paused=false;r.chapterDone=false;r.bossDead=false;r.bossPhase2=false;r.enemies=[];r.shots=[];r.bossFields=[];r.hazards=[];r.attack=999;r.hp=r.maxHp=100000;r.xpNeed=1e8;
  if(mode==='story'){r.story.unlocked=tier;r.story.activeRoom=tier;r.story.combatRoom=tier;r.story.discovered=Array.from({length:tier+1},(_,i)=>i);Object.assign(r.story.rooms[tier],{entered:true,briefed:true,fighting:true,waveSpawned:r.wave});const b=t.storyRoomBoxes[tier];r.x=b.cx;r.y=b.cy}
  t.spawnEnemy(true);const e=r.enemies.find(e=>e.boss);assert(e);if(mode!=='story'){e.x=r.x-150;e.y=r.y-40}e.stun=0;e.cast=null;e.bossRecovery=0;t.ensureBossSkills(e,r);e.shoot=999;return{r,e};
 }
 const bossTick=(e,r,dt)=>t.bossAI(e,r,dt,Math.atan2(r.y-e.y,r.x-e.x),Math.hypot(r.x-e.x,r.y-e.y));
 check('all thirty named bosses have two registered distinct skills with readable warning times',()=>{const ids=new Set(),names=new Set();assert.equal(t.bossSkillBook.length,6);for(let ch=0;ch<6;ch++){assert.equal(t.bossSkillBook[ch].length,5);for(const p of t.bossSkillBook[ch]){assert.equal(p.skills.length,2);assert.notEqual(p.skills[0].kind,p.skills[1].kind);for(const s of p.skills){assert(!ids.has(s.id));assert(!names.has(s.name));ids.add(s.id);names.add(s.name);assert(s.warning>=.95);assert(s.cooldown>s.warning);assert(s.hint&&s.description);assert.equal(t.bossSkillById(s.id).name,s.name)}}}assert.equal(ids.size,60)});
 check('all sixty boss skills render warnings, hold damage until release and perform their advertised effect',()=>{for(let ch=1;ch<=6;ch++)for(let tier=1;tier<=5;tier++)for(let slot=0;slot<2;slot++){const{r,e}=bossScene(ch,tier),s=t.bossProfile(e).skills[slot];e.hp=e.maxHp*.7;const hp=e.hp,playerHP=r.hp,position={x:e.x,y:e.y},n=r.enemies.length;assert(t.beginBossSkill(e,r,slot));t.ctx.clearRect(0,0,800,500);t.ctx.save();t.ctx.translate(400-r.x,250-r.y);t.drawBossSkillEffects(t.ctx,r,.5);t.drawEnemyMotion(t.ctx,e,.5);t.ctx.restore();assert(t.ctx.getImageData(0,0,800,500).data.some((v,i)=>i%4===3&&v>0),s.name+' visible warning');t.updateHud();assert(els['#bossSkillStatus'].textContent.includes(s.name));bossTick(e,r,s.warning-.01);assert(e.bossCast,s.name+' holds warning');assert.equal(r.hp,playerHP);assert.equal(r.shots.length,0);assert.equal(r.bossFields.length,0);bossTick(e,r,.02);assert.equal(e.bossCast,null,s.name+' releases');if(['fan','ring'].includes(s.kind))assert(r.shots.length>0);if(['slam','barrage','beam','lanes','nova'].includes(s.kind))assert(r.bossFields.length>0);if(s.kind==='summon')assert(r.enemies.length>n);if(s.kind==='ritual')assert(e.hp>hp&&e.hp<=e.maxHp);if(s.kind==='charge')assert(e.bossDash);if(s.kind==='blink'){assert(Math.hypot(e.x-position.x,e.y-position.y)>1);assert(r.bossFields.length>0)}if(s.kind==='eclipse'){assert(r.shots.length>0);assert(r.enemies.length>n)}assert(t.validExpedition(t.packRun(r)));t.endRun(false,true);t.closeModal()}});
 check('all boss skill ground marks and teleport destinations stay on story floors',()=>{for(let ch=1;ch<=6;ch++)for(let tier=1;tier<=5;tier++){const{r,e}=bossScene(ch,tier,'story');for(let slot=0;slot<2;slot++){e.bossCast=null;e.bossRecovery=0;e.cast=null;assert(t.beginBossSkill(e,r,slot));for(const p of e.bossCast.points)assert(!t.storySolid(r,p.x,p.y,11),'chapter '+ch+' tier '+tier+' mark');for(const line of e.bossCast.lanes)assert(!t.storySolid(r,line.x2,line.y2,2),'lane ends before cover');e.bossCast=null}t.endRun(false,true);t.closeModal()}});
 check('enrage shortens every boss skill cooldown without shortening its warning',()=>{for(let ch=1;ch<=6;ch++)for(let tier=1;tier<=5;tier++){const{r,e}=bossScene(ch,tier);e.hp=e.maxHp*.49;bossTick(e,r,.01);assert(e.bossEnraged);assert(t.beginBossSkill(e,r,0));const s=t.bossProfile(e).skills[0];assert.equal(e.bossCast.total,s.warning);bossTick(e,r,s.warning+.01);assert(Math.abs(e.bossSkillCd-t.bossDifficultyCooldown(e,r,s))<.001);t.endRun(false,true);t.closeModal()}});
 check('stuns interrupt committed casts, and burst damage breaks healing rituals',()=>{let{r,e}=bossScene(1,1);assert(t.beginBossSkill(e,r,1));e.stun=.5;bossTick(e,r,.01);assert.equal(e.bossCast,null);assert.equal(e.bossDash,null);assert.equal(r.bossFields.length,0);assert.equal(e.bossSkillLabel,'Interrupted');t.endRun(false,true);t.closeModal();({r,e}=bossScene(1,3));e.hp=e.maxHp*.7;assert(t.beginBossSkill(e,r,1));t.hit(e,r.dmg*3);const hp=e.hp;bossTick(e,r,.01);assert.equal(e.bossCast,null);assert.equal(e.bossSkillLabel,'Ritual broken');assert.equal(e.hp,hp);t.endRun(false,true);t.closeModal()});
 check('boss death cancels pending casts and removes owned hazards and projectiles only',()=>{const{r,e}=bossScene(2,2);assert(t.beginBossSkill(e,r,0));t.addBossField(r,e,'circle',{x:r.x,y:r.y,radius:80},100,1);const owned={x:r.x,y:r.y,vx:0,vy:0,t:1,enemy:true,dmg:99,bossOwner:e.bossSkillId},other={x:r.x+50,y:r.y,vx:0,vy:0,t:1,enemy:true,dmg:1,bossOwner:'other'};r.shots.push(owned,other);t.hit(e,1e12,true);assert.equal(e.bossCast,null);assert.equal(e.bossDash,null);assert.equal(r.bossFields.length,0);assert.equal(owned.t,0);assert(!r.shots.includes(owned));assert(r.shots.includes(other));bossTick(e,r,3);assert.equal(r.bossFields.length,0);t.endRun(false,true);t.closeModal()});
 check('boss fields respect armor, shields and hit-once rules, and shockwaves hurt at their edge',()=>{const{r,e}=bossScene(1,1);r.hp=1000;r.damageReduce=.3;r.invuln=0;r.shield=2;t.addBossField(r,e,'circle',{x:r.x,y:r.y,radius:50},100,1);t.tickBossFields(r,.01);assert.equal(r.hp,1000);r.shield=0;t.tickBossFields(r,.01);assert.equal(r.hp,930);r.invuln=0;t.tickBossFields(r,.01);assert.equal(r.hp,930);const ring={shape:'ring',x:r.x-50,y:r.y,radius:150,thickness:20,t:1,max:1};assert(!t.bossFieldContains(r,ring));ring.t=.66;assert(t.bossFieldContains(r,ring));ring.t=.05;assert(!t.bossFieldContains(r,ring));t.endRun(false,true);t.closeModal()});
 check('charge paths and beam damage are stopped by solid Story cover',()=>{for(const tier of[1,2]){const{r,e}=bossScene(2,tier,'story'),m=t.storyTerrain(2),b=t.storyRoomBoxes[tier];let tile=null;for(let y=b.ty+1;y<b.ty+8&&!tile;y++)for(let x=b.tx+1;x<b.tx+10;x++)if(m.tiles[y][x]===2&&m.tiles[y][x-1]===1&&m.tiles[y][x+2]===1){tile={x:x*50,y:y*50};break}assert(tile);e.x=tile.x-45;e.y=tile.y+25;r.x=tile.x+135;r.y=tile.y+25;r.invuln=0;const hp=r.hp,slot=tier===1?1:0;assert(t.beginBossSkill(e,r,slot));assert(e.bossCast.lanes[0].x2<tile.x);t.releaseBossSkill(e,r);if(tier===1)for(let i=0;i<30&&e.bossDash;i++)t.tickBossDash(e,r,.04);else t.tickBossFields(r,.04);assert(e.x<tile.x);assert.equal(r.hp,hp);assert(!t.storySolid(r,e.x,e.y,11));t.endRun(false,true);t.closeModal()}});
 check('mid-cast saves preserve locked targets and remaining warning time, and pause freezes skills',()=>{const{r,e}=bossScene(3,5);assert(t.beginBossSkill(e,r,1));bossTick(e,r,.3);const left=e.bossCast.left,points=JSON.stringify(e.bossCast.points),time=r.time;r.paused=true;t.update(.05);assert.equal(e.bossCast.left,left);assert.equal(r.time,time);t.leaveToHome();assert(t.resumeRun());const resumed=t.run,boss=resumed.enemies.find(e=>e.boss);assert.equal(boss.bossCast.left,left);assert.equal(JSON.stringify(boss.bossCast.points),points);resumed.x+=170;resumed.y+=70;bossTick(boss,resumed,.1);assert.equal(JSON.stringify(boss.bossCast.points),points,'marks never track after tell');assert(boss.bossCast.left<left);assert(t.validExpedition(t.packRun(resumed)));t.endRun(false,true);t.closeModal()});
 check('boss abilities are enabled in Campaign, Story and Endless and their guide closes correctly',()=>{for(const mode of['campaign','story','endless']){const{r,e}=bossScene(1,1,mode);e.bossSkillCd=0;bossTick(e,r,.01);assert(e.bossCast);const left=e.bossCast.left;t.openBossSkillGuide();assert(r.paused);assert(els['#modal'].open);t.update(.05);assert.equal(e.bossCast.left,left);els['#modalActions'].children[0].click();assert(!els['#modal'].open);assert(!r.paused);t.endRun(false,true);t.closeModal()}});
 check('reinforcements and special projectiles remain capped during repeated boss casts',()=>{const{r,e}=bossScene(6,5);for(let i=0;i<25;i++){e.bossCast=null;e.bossRecovery=0;e.cast=null;e.bossDash=null;assert(t.beginBossSkill(e,r,1));t.releaseBossSkill(e,r)}assert(r.enemies.length<=28);assert(r.shots.length<=280);assert((r.bossFields||[]).length<=36);assert(t.validExpedition(t.packRun(r)));t.endRun(false,true);t.closeModal()});
 check('a blink lands on its marked Story destination without the walking collision sweep pulling it back',()=>{const{r,e}=bossScene(1,2,'story');assert(t.beginBossSkill(e,r,0));const marked={...e.bossCast.points[0]},from={x:e.x,y:e.y};t.releaseBossSkill(e,r);t.storyMoveEnemy(r,e,from);assert.equal(e.x,marked.x);assert.equal(e.y,marked.y);assert(!t.storySolid(r,e.x,e.y,11));assert(!e.bossJustTeleported);t.endRun(false,true);t.closeModal()});
 check('active skill fields retain ownership and lifetime across Continue',()=>{const{r,e}=bossScene(2,2);assert(t.beginBossSkill(e,r,0));t.releaseBossSkill(e,r);assert(r.bossFields.length);r.x+=250;t.tickBossFields(r,.1);const owner=r.bossFields[0].owner,left=r.bossFields[0].t;t.leaveToHome();assert(t.resumeRun());assert.equal(t.run.bossFields[0].owner,owner);assert.equal(t.run.bossFields[0].t,left);t.update(.05);assert(t.run.bossFields[0].t<left);assert(t.validExpedition(t.packRun(t.run)));t.endRun(false,true);t.closeModal()});
 check('a projectile cannot hit the player later in the same frame after its boss dies',()=>{const{r,e}=bossScene(1,1);e.bossSkillCd=999;r.invuln=0;r.shield=0;const hp=r.hp;r.shots=[{x:e.x,y:e.y,vx:0,vy:0,t:2,enemy:false,dmg:1e12,pierce:false,hit:new Set(),color:'#fff0cd'},{x:r.x,y:r.y,vx:0,vy:0,t:2,enemy:true,dmg:99999,bossOwner:e.bossSkillId,color:'#f49b8d'}];t.update(.01);assert(e.hp<=0);assert.equal(r.hp,hp);t.endRun(false,true);t.closeModal()});

 check('twelve offline pixel-effect atlases contain 96 distinct transparent animation cells',()=>{let total=0;for(const kind of Object.keys(t.combatPalette)){const atlas=t.combatAtlas(kind),g=atlas.getContext('2d'),hashes=new Set();assert.equal(atlas.width,256);assert.equal(atlas.height,32);for(let f=0;f<8;f++){const pixels=g.getImageData(f*32,0,32,32).data;assert(pixels.some((v,i)=>i%4===3&&v>0),kind);assert.equal(pixels[3],0);hashes.add(crypto.createHash('sha256').update(pixels).digest('hex'));total++}assert.equal(hashes.size,8,kind+' has eight authored frames')}assert.equal(total,96)});
 check('all eighteen hero skill visuals start at actual release and animate without dealing cosmetic damage',()=>{const shapes=new Set();for(const h of t.heroes)for(const skill of t.skillBook[h.classId]){t.run=null;t.save=t.fresh();t.save.hero=h.id;t.save.unlocked.push(h.id);t.save.skills[h.classId]=skill[0];t.save.skillRanks[skill[0]]=1;t.chosenMode='campaign';t.startRun();const r=t.run;r.enemies=[];r.shots=[];r.combatFx=[];t.spawnEnemy(false,0);const e=r.enemies[0];e.x=r.x+60;e.y=r.y;e.hp=e.maxHp=1e7;r.skillCd=0;t.skill();if(r.skillPending||r.altPending)assert(!(r.combatFx||[]).some(f=>f.kind==='heroSkill'),skill[0]+' no early burst');let visual;for(let i=0;i<30&&!visual;i++){t.tickSpriteAnimation(r,.025);visual=(r.combatFx||[]).find(f=>f.kind==='heroSkill')}assert(visual,skill[0]+' release effect');assert.equal(visual.skill,skill[0]);shapes.add(visual.shape);const hp=e.hp,gold=t.save.gold,hashes=new Set();for(const age of [.1,.35,.7]){visual.age=age;t.ctx.clearRect(0,0,800,500);t.ctx.save();t.ctx.translate(400-r.x,300-r.y);t.drawCombatEffects(t.ctx,r);t.ctx.restore();hashes.add(crypto.createHash('sha256').update(t.ctx.getImageData(0,0,800,500).data).digest('hex'))}assert.equal(hashes.size,3,skill[0]+' visibly progresses');assert.equal(e.hp,hp);assert.equal(t.save.gold,gold);t.endRun(false,true);t.closeModal()}assert.equal(shapes.size,16)});
 check('projectile sprites and muzzle effects preserve every ranged weapon origin in both facings',()=>{for(const w of t.weapons.filter(w=>!['keeper','brawler'].includes(w.classId)))for(const heading of [-1,1]){t.run=null;t.save=t.fresh();const h=t.heroes.find(h=>h.classId===w.classId);t.save.hero=h.id;t.save.unlocked.push(h.id);t.chosenMode='campaign';t.startRun();const r=t.run;r.weapon=w;r.heading=r.attackFacing=heading;r.enemies=[];r.shots=[];r.combatFx=[];t.spawnEnemy(false,0);const e=r.enemies[0];e.x=r.x+heading*170;e.y=r.y-60;t.releaseClassAttack(r);const origin=t.firingPoint(r);assert(r.shots.length);for(const s of r.shots){assert.equal(s.x,origin.x);assert.equal(s.y,origin.y);assert(t.combatPalette[s.vfxKind]);assert.equal(s.vfxTrail.length,0)}const muzzle=r.combatFx.find(f=>f.kind==='muzzle');assert.equal(muzzle.x,origin.x);assert.equal(muzzle.y,origin.y);t.endRun(false,true);t.closeModal()}});
 check('projectile trails follow sampled travel and animate during flight without mutating physics in draw',()=>{const r=reset();r.enemies=[];r.shots=[];r.combatFx=[];const s={x:r.x,y:r.y-40,vx:100,vy:20,t:5,enemy:true,dmg:1};r.shots.push(s);const positions=[];for(let i=0;i<20;i++){const from={x:s.x,y:s.y};positions.push(from);t.sampleCombatShot(r,s,from,.02);s.x+=s.vx*.02;s.y+=s.vy*.02}assert(s.vfxTrail.length<=7);assert(s.vfxTrail.length>=4);for(const p of s.vfxTrail)assert(positions.some(q=>p.x===q.x&&p.y===q.y));s.vfxAge=.4;const state=JSON.stringify(s),hashes=new Set();for(const age of [.1,.24,.4]){s.vfxAge=age;t.ctx.clearRect(0,0,800,500);t.ctx.save();t.ctx.translate(300-r.x,200-r.y);t.drawCombatProjectiles(t.ctx,r);t.ctx.restore();hashes.add(crypto.createHash('sha256').update(t.ctx.getImageData(0,0,800,500).data).digest('hex'))}s.vfxAge=.4;assert.equal(JSON.stringify(s),state);assert.equal(hashes.size,3);t.endRun(false,true);t.closeModal()});
 check('enemy cast art is delayed to projectile release and matches its source for all chapters',()=>{for(let chapter=1;chapter<=6;chapter++){const r=reset();r.chapter=chapter;r.enemies=[];r.shots=[];r.combatFx=[];t.spawnEnemy(false,2);const e=r.enemies[0];t.queueEnemyCast(e,[{angle:0,speed:100,dmg:10}]);t.tickEnemyCast(e,r,.1);assert.equal(r.combatFx.length,0);t.tickEnemyCast(e,r,.4);assert.equal(r.shots.length,1);const s=r.shots[0],fx=r.combatFx.find(f=>f.kind==='enemyCast');assert(fx);assert.equal(fx.x,s.x);assert.equal(fx.y,s.y);assert.equal(fx.theme,s.vfxKind);t.endRun(false,true);t.closeModal()}});
 check('all sixty boss abilities produce animated themed release effects with owner cleanup',()=>{const mechanics=new Set();for(let ch=1;ch<=6;ch++)for(let tier=1;tier<=5;tier++)for(let slot=0;slot<2;slot++){const{r,e}=bossScene(ch,tier);r.combatFx=[];assert(t.beginBossSkill(e,r,slot));const name=t.bossProfile(e).skills[slot];mechanics.add(name.kind);t.releaseBossSkill(e,r);const fx=r.combatFx.find(f=>f.kind==='bossRelease');assert(fx,name.name);assert.equal(fx.owner,e.bossSkillId);const hp=r.hp;t.ctx.save();t.ctx.translate(350-e.x,250-e.y);t.drawCombatBossForeground(t.ctx,r);t.drawCombatEffects(t.ctx,r);t.ctx.restore();assert.equal(r.hp,hp,'render cannot damage');for(const field of r.bossFields)assert(t.combatPalette[field.vfxTheme]);t.hit(e,1e12);t.updateWorld(r,.01);assert(!r.combatFx.some(f=>f.owner===e.bossSkillId));t.endRun(false,true);t.closeModal()}assert.equal(mechanics.size,12)});
 check('combat visual state is bounded, pauses with gameplay, and is omitted from Continue data',()=>{const r=reset();r.enemies=[];r.spawn=999;r.attack=999;r.combatFx=[];for(let i=0;i<400;i++)t.addCombatFx(r,'impact',r.x,r.y,{size:25});assert.equal(r.combatFx.length,96);t.shoot(r.x,r.y,0,10,300,true);const s=r.shots[0];t.sampleCombatShot(r,s,{x:r.x,y:r.y},.02);const age=r.combatFx[0].age;r.paused=true;t.update(.05);assert.equal(r.combatFx[0].age,age);const packed=t.packRun(r);assert(!('combatFx'in packed.state));assert(!('vfxTrail'in packed.state.shots[0]));assert(t.validExpedition(packed));r.paused=false;t.tickSpriteAnimation(r,2);assert.equal(r.combatFx.length,0);t.endRun(false,true);t.closeModal()});
 check('cover impacts use the swept collision point and full combat renders in all three modes',()=>{const r=storyReset(),map=t.storyTerrain(1),prop=map.props.find(p=>!r.story.destroyed.includes(p.id));assert(prop);const s={x:prop.x+prop.w+35,y:prop.y+prop.h/2,vx:500,vy:0,t:2,enemy:false,dmg:1,pierce:false,hit:new Set()};assert(t.storyProjectileCollision(r,s,prop.x-35,s.y));assert(s.vfxCollision);assert(s.vfxCollision.x<prop.x+prop.w);assert.equal(s.t,0);t.endRun(false,true);t.closeModal();for(const mode of ['campaign','story','endless']){const{r,e}=bossScene(2,2,mode);r.skillFields=[{x:r.x,y:r.y,t:3,r:125,heal:1,tick:1,dmg:1}];r.sentries=[{x:r.x-30,y:r.y-20,t:4,fire:1,dmg:1}];r.chests=[{x:r.x+30,y:r.y+10}];r.drops=[{x:r.x-20,y:r.y+15,value:1}];r.skillCd=0;t.skill();for(let i=0;i<14;i++)t.tickSpriteAnimation(r,.025);e.bossCast=null;e.bossRecovery=0;e.cast=null;t.beginBossSkill(e,r,0);t.releaseBossSkill(e,r);const hp=r.hp;t.draw(r.time);assert.equal(r.hp,hp);assert(t.validExpedition(t.packRun(r)));assert(t.ctx.getImageData(0,0,800,500).data.some((v,i)=>i%4===3&&v>0));if(mode==='story')fs.writeFileSync(path.join(root,'tests/combat-gameplay.png'),game.toBuffer('image/png'));t.endRun(false,true);t.closeModal()}});


 function weaponScene(w){if(t.run){t.endRun(false,true);t.closeModal()}t.run=null;t.save=t.fresh();const h=t.heroes.find(h=>h.classId===w.classId);t.save.hero=h.id;t.save.unlocked.push(h.id);t.save.weapon=w.id;t.save.unlockedWeapons.push(w.id);t.save.classLoadouts={[h.classId]:w.id};t.chosenMode='campaign';t.startRun();const r=t.run;r.weapon=w;r.enemies=[];r.shots=[];r.combatFx=[];r.attack=0;r.skillCd=999;r.spawn=999;r.hp=r.maxHp=1e9;r.xpNeed=1e9;t.spawnEnemy(false,0);const e=r.enemies[0];e.x=r.x+(w.classId==='keeper'||w.classId==='brawler'?55:180);e.y=r.y-5;e.hp=e.maxHp=1e9;e.speed=0;e.shoot=999;e.traitCd=999;e.attack=999;r.critChance=0;return{r,e,h}}
 check('all 31 weapons have full attack clips and unique tiered signature profiles',()=>{assert.equal(Object.keys(t.weaponAttackProfiles).length,31);const signatures=new Set();for(const w of t.weapons){const id=t.actionBindings[w.id].attack,d=t.providedActions[id],p=t.weaponAttackProfiles[w.id];assert(d&&t.spriteImages['action_'+id]?.loaded,w.id+' complete art');assert(d.frames>=7);assert.equal(p.tier,w.tier);assert(p.releasePhase>.3&&p.releasePhase<.7);assert(p.edges.every((x,i)=>i===0||x>p.edges[i-1]));assert(Math.abs(p.edges.at(-1)-1)<1e-12);assert(!signatures.has(p.signature));signatures.add(p.signature)}assert.equal(Object.keys(t.weaponAttackAdditions).length,13)});
 check('104 new poses have transparent borders and complete registered body footprints',()=>{let frames=0;for(const[id,d]of Object.entries(t.weaponAttackAdditions)){const im=t.spriteImages['action_'+id],canvas=createCanvas(d.width,d.height),g=canvas.getContext('2d'),hashes=new Set();for(let f=0;f<8;f++){g.clearRect(0,0,d.width,d.height);g.drawImage(im,f*d.width,0,d.width,d.height,0,0,d.width,d.height);const pixels=g.getImageData(0,0,d.width,d.height).data;assert(pixels.some((v,i)=>i%4===3&&v>0));for(const[x,y]of[[0,0],[255,0],[0,191],[255,191]])assert.equal(g.getImageData(x,y,1,1).data[3],0,id+' border');hashes.add(crypto.createHash('sha256').update(pixels).digest('hex'));const point=d.points[f].muzzle;assert(point.every(Number.isFinite));assert(point[0]>-120&&point[0]<145&&point[1]<0&&point[1]>-150);frames++}assert(hashes.size>=7,id+' changes actual poses');assert.equal(d.completeBody,true)}assert.equal(frames,104)});
 check('every weapon anticipates then releases once at its registered contact frame',()=>{for(const w of t.weapons){const{r,e}=weaponScene(w);t.classAttack(r);assert(r.action&&r.pendingStrike>0,w.id);const hp=e.hp,release=r.pendingStrike;assert.equal(t.currentAction(r).frame,0);for(let age=0;age<release-.006;age+=.005){const dt=Math.min(.005,release-.006-age);if(dt>0)t.update(dt)}assert.equal(e.hp,hp,w.id+' no early hit');assert.equal(r.shots.length,0,w.id+' no early projectile');assert(!r.combatFx.some(f=>f.kind==='weaponStrike'));t.update(.012);const bursts=r.combatFx.filter(f=>f.kind==='weaponStrike');assert.equal(bursts.length,1,w.id+' one release event');assert.equal(t.currentAction(r).frame,t.providedActions[r.action.id].release,w.id+' contact pose');assert(e.hp<hp||r.shots.length>0,w.id+' actual attack');assert.equal(r.lastWeaponRelease.frame,t.providedActions[r.action.id].release);r.attack=999;for(let i=0;i<8;i++)t.update(.01);assert.equal(r.combatFx.filter(f=>f.kind==='weaponStrike').length,1,w.id+' no duplicate damage-release VFX');t.endRun(false,true);t.closeModal()}});
 check('weapon motion and new release effects preserve firing points in both directions',()=>{for(const w of t.weapons)for(const heading of[-1,1]){const{r,e}=weaponScene(w);e.x=r.x+heading*(w.classId==='keeper'||w.classId==='brawler'?55:180);r.heading=heading;t.classAttack(r);r.action.elapsed=r.action.duration*t.weaponAttackProfiles[w.id].releasePhase;r.pendingStrike=null;r.heading=r.attackFacing=heading;t.releaseClassAttack(r);const point=t.firingPoint(r),fx=r.combatFx.find(f=>f.kind==='weaponStrike');assert(fx,w.id);assert.equal(fx.x,point.x);assert.equal(fx.y,point.y);for(const shot of r.shots){assert.equal(shot.x,point.x,w.id+' horizontal tip');assert.equal(shot.y,point.y,w.id+' vertical tip');assert.equal(shot.vfxWeapon,w.id);assert.equal(shot.vfxTier,w.tier)}t.endRun(false,true);t.closeModal()}});
 check('all weapon signatures animate distinctly, and legendary and mythic details increase without damage',()=>{const canvas=createCanvas(220,160),g=canvas.getContext('2d'),hashes=new Set();for(const w of t.weapons){const p=t.weaponAttackProfiles[w.id],frames=new Set();for(const age of[.03,.13,.22]){g.clearRect(0,0,220,160);const fx={...p,weaponId:w.id,kind:'weaponStrike',x:80,y:80,angle:0,age,life:.5};t.drawWeaponStrike(g,fx);frames.add(crypto.createHash('sha256').update(g.getImageData(0,0,220,160).data).digest('hex'))}assert.equal(frames.size,3,w.id);hashes.add([...frames][1]);assert.equal(p.detail,2+w.tier*2)}assert.equal(hashes.size,31);const{r,e}=weaponScene(t.weapons.find(w=>w.id==='harbinger')),hp=e.hp,gold=t.save.gold;t.drawWeaponStrike(g,{...t.weaponAttackProfiles.harbinger,weaponId:'harbinger',x:80,y:80,age:.1,life:.5});assert.equal(e.hp,hp);assert.equal(t.save.gold,gold);t.endRun(false,true);t.closeModal()});
 check('new attack cycles pause, cancel on dash and resume exactly through Continue',()=>{const{r}=weaponScene(t.weapons.find(w=>w.id==='titan'));t.classAttack(r);t.update(.06);const elapsed=r.action.elapsed,pending=r.pendingStrike;r.paused=true;t.update(.05);assert.equal(r.action.elapsed,elapsed);assert.equal(r.pendingStrike,pending);r.paused=false;t.leaveToHome();assert(t.resumeRun());assert.equal(t.run.action.elapsed,elapsed);assert.equal(t.run.pendingStrike,pending);t.keys.add('d');t.dash();assert.equal(t.run.action,null);assert.equal(t.run.pendingStrike,null);t.keys.clear();t.endRun(false,true);t.closeModal()});
 check('the Seraph Lantern stays visibly present at every registered pose including contact',()=>{const d=t.weaponAttackAdditions.attackv3_seraph,im=t.spriteImages.action_attackv3_seraph,canvas=createCanvas(d.width,d.height),g=canvas.getContext('2d');for(let frame=0;frame<8;frame++){g.clearRect(0,0,d.width,d.height);g.drawImage(im,frame*d.width,0,d.width,d.height,0,0,d.width,d.height);const pt=d.points[frame].muzzle,x=Math.max(0,Math.floor(d.anchor[0]+pt[0]-14)),y=Math.max(0,Math.floor(d.anchor[1]+pt[1]-14)),pix=g.getImageData(x,y,28,28).data;let gold=0;for(let i=0;i<pix.length;i+=4)if(pix[i+3]>100&&pix[i]>130&&pix[i+1]>80&&pix[i+2]<180)gold++;assert(gold>20,'frame '+frame+' keeps its gold lantern chamber')}});

 check('all 1800 successive waves scale health damage and pressure across chapter and Endless boundaries',()=>{const r=reset('endless');let last=null;for(let n=1;n<=1800;n++){r.cycle=Math.floor((n-1)/600);r.chapter=Math.floor((n-1)%600/100)+1;r.wave=(n-1)%100+1;const p=t.difficultyProfile(r);r.enemies=[];t.spawnEnemy(false,0);const e=r.enemies[0];assert.equal(p.wave,n);if(last){assert(e.hp>last.hp,'health wave '+n);assert(e.dmg>last.dmg,'damage wave '+n);assert(e.speed>=last.speed);assert(p.interval<=last.p.interval);assert(p.cap>=last.p.cap);assert(p.storyCount>=last.p.storyCount);assert(p.bossTempo<=last.p.bossTempo)}assert(e.speed<120);last={hp:e.hp,dmg:e.dmg,speed:e.speed,p}}r.cycle=20;const a=t.difficultyProfile(r);r.cycle=21;assert(t.difficultyProfile(r).vitality>a.vitality);t.endRun(false,true);t.closeModal()});
 check('all successive bosses grow stronger across realm and Endless boundaries',()=>{const r=reset('endless');let prev=null;for(let i=1;i<=60;i++){const n=i*20;r.cycle=Math.floor((n-1)/600);r.chapter=Math.floor((n-1)%600/100)+1;r.wave=(n-1)%100+1;r.enemies=[];t.spawnEnemy(true);const e=r.enemies[0];if(prev){assert(e.hp>prev.hp);assert(e.dmg>prev.dmg)}prev={hp:e.hp,dmg:e.dmg};assert(t.validExpedition(t.packRun(r)))}t.endRun(false,true);t.closeModal()});
 check('elites arrive every five ordinary waves and milestone bosses remain every twenty',()=>{const r=reset();for(const wave of[5,10,15,20,25,40,95,100]){r.wave=wave-1;r.waveTime=0;r.enemies=[];r.spawn=999;t.advanceWaves(r,30);assert.equal(r.wave,wave);assert.equal(r.enemies.filter(e=>e.boss).length,wave%20===0?1:0);assert.equal(r.enemies.filter(e=>e.elite).length,wave%20===0?0:1)}t.endRun(false,true);t.closeModal()});
 check('spawn caps count living enemies and handle dead bodies',()=>{const r=reset();r.chapter=6;r.wave=99;r.enemies=[];for(let i=0;i<100;i++){r.spawn=0;t.advanceWaves(r,.001)}assert.equal(r.enemies.length,150);r.enemies[0].hp=0;r.spawn=0;t.advanceWaves(r,.001);assert.equal(r.enemies.filter(e=>e.hp>0).length,150);t.endRun(false,true);t.closeModal()});
 check('Story crowds scale across six chapters with elites and solid-floor spawning',()=>{const r=storyReset();for(let ch=1;ch<=6;ch++)for(const wave of[1,5,19,21,55,99]){r.chapter=ch;t.setupChapter(r);r.paused=false;const stage=Math.ceil(wave/20),b=t.storyRoomBoxes[stage];r.story.unlocked=stage;r.story.activeRoom=stage;r.story.combatRoom=stage;r.x=b.cx;r.y=b.cy;Object.assign(r.story.rooms[stage],{fighting:true,waveSpawned:0});r.wave=wave;r.enemies=[];t.advanceWaves(r,.01);assert.equal(r.enemies.length,t.difficultyProfile(r).storyCount);assert.equal(r.enemies.filter(e=>e.elite).length,wave%5===0?1:0);assert(r.enemies.every(e=>!t.storySolid(r,e.x,e.y,7)))}t.endRun(false,true);t.closeModal()});
 check('Story reinforcements are paced bounded frozen on pause and resumable',()=>{const{r,e}=bossScene(6,5,'story');r.spawn=2;r.enemies=[e];r.paused=true;t.advanceWaves(r,1);assert.equal(r.spawn,2);r.paused=false;t.advanceWaves(r,1);assert.equal(r.enemies.length,1);t.leaveToHome();assert(t.resumeRun());const q=t.run;assert.equal(q.spawn,1);t.advanceWaves(q,1.1);assert(q.enemies.length>1);for(let i=0;i<30;i++)t.advanceWaves(q,13);assert(q.enemies.length<=t.difficultyProfile(q).escorts+4);const count=q.enemies.length;q.enemies.find(e=>e.boss).hp=0;t.advanceWaves(q,100);assert.equal(q.enemies.length,count);assert(t.validExpedition(t.packRun(q)));t.endRun(false,true);t.closeModal()});
 check('bosses chain exactly two or three full-warning skills and then recover',()=>{for(let ch=1;ch<=6;ch++)for(let tier=1;tier<=5;tier++)for(const phase of[2,3]){const{r,e}=bossScene(ch,tier);e.hp=e.maxHp*(phase===2?.4:.2);e.bossSkillCd=0;let releases=0,prev=false;for(let i=0;i<500;i++){const was=!!e.bossCast;bossTick(e,r,.02);if(was&&!e.bossCast)releases++;if(e.bossCast&&!prev){assert.equal(e.bossCast.total,t.bossSkillById(e.bossCast.id).warning)}prev=!!e.bossCast;if(releases===phase&&!e.bossDash){assert(!e.bossComboNext);assert(!e.bossComboActive);assert(e.bossSkillCd>0);break}}assert.equal(releases,phase,'chapter '+ch+' tier '+tier+' phase '+phase);t.endRun(false,true);t.closeModal()}});
 check('boss stagger protection prevents permanent stun while leaving rituals interruptible',()=>{const{r,e}=bossScene(1,3);assert(t.beginBossSkill(e,r,0));e.stun=3;bossTick(e,r,.01);assert(!e.bossCast);assert(e.bossStaggerGuard>0);for(let i=0;i<35;i++){e.stun=3;bossTick(e,r,.02)}assert.equal(e.bossStunLeft,0);e.bossRecovery=0;assert(t.beginBossSkill(e,r,1));t.hit(e,r.dmg*3);bossTick(e,r,.01);assert.equal(e.bossSkillLabel,'Ritual broken');t.endRun(false,true);t.closeModal()});
 check('mid-combo Continue preserves phase remaining casts and stagger protection',()=>{const{r,e}=bossScene(4,4);e.hp=e.maxHp*.2;assert(t.beginBossSkill(e,r,1));bossTick(e,r,.2);const left=e.bossCast.left,remaining=e.bossComboRemaining;e.bossStaggerGuard=1.5;t.leaveToHome();assert(t.resumeRun());const q=t.run.enemies.find(e=>e.boss);assert.equal(q.bossCast.left,left);assert.equal(q.bossComboRemaining,remaining);assert.equal(q.bossStaggerGuard,1.5);t.run.paused=true;t.update(.05);assert.equal(q.bossCast.left,left);assert.equal(q.bossStaggerGuard,1.5);t.run.paused=false;t.hit(q,1e12,true);assert(!q.bossComboActive&&!q.bossComboNext);t.endRun(false,true);t.closeModal()});
 check('chapter trait attacks have scaled damage and a complete warning',()=>{const r=reset();r.chapter=5;r.wave=90;r.enemies=[];t.spawnEnemy(false,2);const e=r.enemies[0];e.x=r.x+100;e.y=r.y;e.traitCd=0;e.cast=null;e.stun=0;r.shots=[];r.hazards=[];t.enemyTrait(e,r,.01,Math.PI,100);assert(e.cast);assert.equal(r.shots.length,0);assert.equal(e.cast.total,.38);assert(e.cast.shots.every(s=>s.dmg>19));const count=e.cast.shots.length;t.tickEnemyCast(e,r,.2);assert.equal(r.shots.length,0);t.tickEnemyCast(e,r,.2);assert.equal(r.shots.length,count);t.endRun(false,true);t.closeModal()});


 check('chapter introductions acknowledge only this journey’s earlier decision in both branches',()=>{const r=storyReset();t.save.storyDecisions={1:'proof'};for(let ch=2;ch<=6;ch++){r.chapter=ch;t.setupChapter(r);for(const choice of ['care','proof']){r.storyChoices={[ch-1]:choice};const text=t.storyDialogueLines(r,{kind:'intro',stage:0}).lines.map(l=>l.text).join(' ');assert(text.includes(t.storyChoiceEcho(ch-1,choice)));assert(!text.includes(t.storyChoiceEcho(ch-1,choice==='care'?'proof':'care')))}r.storyChoices={};const text=t.storyDialogueLines(r,{kind:'intro',stage:0}).lines.map(l=>l.text).join(' ');assert(!text.includes(t.storyChoiceEcho(ch-1,'proof')))}t.endRun(false,true);t.closeModal()});
 check('each hero speaks in introductions and every decision and trader conversation terminates',()=>{const r=storyReset();for(const hero of t.heroes){r.hero=hero;for(let ch=1;ch<=6;ch++){r.chapter=ch;t.setupChapter(r);const intro=t.storyDialogueLines(r,{kind:'intro',stage:0});assert(intro.lines.some(l=>l.speaker===hero.name&&l.text.length>20));for(const kind of ['intro','guide','brief','report','merchant','repeat']){const dialogue=t.storyDialogueLines(r,{kind,stage:kind==='report'?4:kind==='brief'?1:0});assert(dialogue.lines.length>0&&dialogue.lines.length<12);assert(dialogue.lines.every(l=>typeof l.text==='string'&&l.text.length>0))}}}t.endRun(false,true);t.closeModal()});
 check('finishing a new story replaces earlier journey decisions and both endings preserve their costs',()=>{for(const ending of ['release','keep']){const r=storyReset();t.save.storyDecisions={1:'proof',2:'proof',3:'proof'};r.storyChoices={1:'care',2:'care'};r.pendingEnding=true;t.finishStory(ending);assert.equal(t.save.storyDecisions[1],'care');assert.equal(t.save.storyDecisions[3],undefined);const text=t.endingText(ending);assert(text.includes('2 people-first decisions; 0 proof-first decisions'));assert(text.includes(ending==='release'?'does not make her alive again':'politeness of a stranger'));t.showPage('journal');assert(els['#shop'].innerHTML.includes(t.storyChoiceEcho(1,'care')));assert(!els['#shop'].innerHTML.includes(t.storyChoiceEcho(3,'proof')));t.closeModal()}});

